function measure(){W=document.documentElement.clientWidth;H=innerHeight;target=scrollY;scroll=target;chapterEls.forEach(el=>{let pin=el.querySelector('.pin');metrics[el.id]={start:el.offsetTop,span:Math.max(1,el.offsetHeight-pin.offsetHeight),height:el.offsetHeight,pinHeight:pin.offsetHeight}});projectSpacing=W<600?W*1.16:W*1.08;$('#project-path').setAttribute('viewBox',`0 0 ${W} 200`);$('#project-path path').setAttribute('d',`M -80 130 C ${W*.25} -80 ${W*.7} 280 ${W+80} 70`);const l=portalLayout(W,metrics.wander.pinHeight);$('.portal-space').style.perspective=l.focal+'px';rings.forEach(r=>{r.style.width=r.style.height=l.radius*2*PORTAL.artExtent+'px'});if(webgl)webgl.resize(W,metrics.wander.pinHeight);const ratio=Math.min(devicePixelRatio,1.5);stars.width=W*ratio;stars.height=H*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);let seed=31;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};particles=Array.from({length:W<600?45:85},(_,i)=>({x:rand()*W,y:rand()*H,r:rand()*.7+.25,phase:rand()*6.28,layer:rand()+.3,gold:i%17===0}));dirty=true}
